  "items": [
    {
      "name": "MvPolynomial.totalDegree_le_degrees_card",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (p : MvPolynomial σ R), p.totalDegree ≤ p.degrees.card"
    },
    {
      "name": "MvPowerSeries.order",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "definition",
      "type": "{σ : Type u_1} → {R : Type u_2} → [Semiring R] → MvPowerSeries σ R → ℕ∞"
    },
    {
      "name": "MvPolynomial.schwartz_zippel_sup_sum",
      "module_name": "Mathlib.Algebra.MvPolynomial.SchwartzZippel",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] [IsDomain R] [inst_2 : DecidableEq R] {n : ℕ} {p : MvPolynomial (Fin n) R},\n  p ≠ 0 →\n    ∀ (S : Fin n → Finset R),\n      ↑{x ∈ Fintype.piFinset fun i => S i | (MvPolynomial.eval x) p = 0}.card / ∏ i, ↑(S i).card ≤\n        p.support.sup fun s => ∑ i, ↑(s i) / ↑(S i).card"
    },
    {
      "name": "MvPolynomial.totalDegree_eq",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (p : MvPolynomial σ R),\n  p.totalDegree = p.support.sup fun m => (Finsupp.toMultiset m).card"
    },
    {
      "name": "MvPolynomial.totalDegree",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "definition",
      "type": "{R : Type u} → {σ : Type u_1} → [inst : CommSemiring R] → MvPolynomial σ R → ℕ"
    }
  ]
}

