      "module": "Mathlib.RingTheory.MvPowerSeries.Order"
    },
    {
      "name": "MvPowerSeries.weightedOrder_one",
      "type": " {σ : Type u_1} {R : Type u_2} [Semiring R] (w : σ → ℕ) [Nontrivial R] : MvPowerSeries.weightedOrder w 1 = 0",
      "module": "Mathlib.RingTheory.MvPowerSeries.Order"
    },
    {
      "name": "MvPowerSeries.weightedOrder_eq_top_iff",
      "type": " {σ : Type u_1} {R : Type u_2} [Semiring R] (w : σ → ℕ) {f : MvPowerSeries σ R} : MvPowerSeries.weightedOrder w f = ⊤ ↔ f = 0",
