    },
    {
      "name": "MvPowerSeries.ne_zero_iff_weightedOrder_finite",
      "type": " {σ : Type u_1} {R : Type u_2} [Semiring R] (w : σ → ℕ) {f : MvPowerSeries σ R} : f ≠ 0 ↔ ↑(MvPowerSeries.weightedOrder w f).toNat = MvPowerSeries.weightedOrder w f",
      "module": "Mathlib.RingTheory.MvPowerSeries.Order"
    }
  ]
